import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`solo-practice-audit`,heroTitle:`Audit your solo practice in minutes`,heroSubtitle:`Perplexity Computer reviews your solo practice site, offers, intake flow, and local presence, then shows what to fix to win better-fit clients.`,inputUrlCta:`Audit my practice`,inputUrlPlaceholder:`yourpractice.com`,inputUrlPrefill:`Go to {url} and run a full solo practice audit. 1) Review the website, service pages, bio, pricing or consultation language, contact flow, reviews, and local visibility. 2) Analyze whether the practice clearly explains who it helps, what outcomes it delivers, and why a prospect should reach out. 3) Benchmark nearby or niche competitors for positioning, proof, pricing cues, and intake clarity. 4) Recommend the highest-impact fixes for better-fit inquiries, trust, and conversion. 5) Deliver a prioritized action plan with rewritten copy, intake improvements, and local growth recommendations.`,heroOverlaySteps:[`Reviewing your site, service pages, bio, offers, reviews, and inquiry flow`,`Benchmarking nearby and niche competitors for positioning and trust signals`,`Prioritizing fixes that can improve better-fit inquiries and conversion`,`Solo practice audit, copy updates, and growth plan ready to use`],generatingSteps:[`Visiting {url} to understand your practice, services, and inquiry journey`,`Designing an agent to benchmark local and niche competitors`,`Configuring copy rewrites, intake-flow fixes, and trust-signal improvements`,`Setting up a prioritized plan to improve client acquisition`],featureSectionTitle:`From unclear positioning to better-fit inquiries`,featureCardTitles:[`Connects to your practice stack`,`Fixes you can apply now`],featureCardDescriptions:[`Computer separates your practice audit into site review, positioning analysis, local benchmarking, and intake recommendations, then routes each step to the right model.`,`Your website, Google Business Profile, Docs, Sheets, and CRM notes can feed one workflow so edits and next steps stay coordinated.`,`Homepage rewrites. Service-page fixes. Trust-signal recommendations. Intake improvements. Computer gives you an action plan tied to stronger inquiries.`],capabilitySectionTitle:`Your practice growth analyst, on demand`,capabilitySectionSubtitle:`Paste your practice site, step away, and come back to a clearer plan for better leads.`,capabilityCards:[{title:`Website and Offer Audit`,description:`Computer can review your homepage, services, bio, offers, and CTAs to find the friction hurting inquiries.`},{title:`Competitor Benchmarking`,description:`Computer can compare your positioning, proof, and intake flow against nearby or niche competitors.`},{title:`Messaging Improvements`,description:`Computer can rewrite your value proposition, service copy, and consultation CTAs so prospects understand why to contact you.`},{title:`Connect Your Tools`,description:`Computer can organize findings across your website, Google Business Profile, Docs, Sheets, and CRM notes.`},{title:`Remember Your Practice`,description:`Computer can remember your services, ideal clients, and positioning so future audits start with relevant context.`},{title:`Refresh the Audit`,description:`Computer can revisit your presence over time and recommend the next updates as reviews, offers, and competitors change.`}]});export{t as default};
